x = Symbol('x')

def nolim_at(N, D, a):
    """N/D 의 x->a 극한이 (유한값으로) 존재하지 않으면 True"""
    Np, Dp = Poly(expand(N), x), Poly(expand(D), x)
    if Dp.is_zero:
        return True
    G = gcd(Np, Dp)
    D1 = quo(Dp, G)
    return D1.eval(a) == 0

def all_ok(N, D):
    """모든 실수 a 에서 극한이 존재하면 True"""
    Np, Dp = Poly(expand(N), x), Poly(expand(D), x)
    G = gcd(Np, Dp)
    D1 = quo(Dp, G)
    return D1.count_roots() == 0

def cand():
    best = []
    for a in range(-15, 16):
        for b in range(-20, 21):
            f = lambda t: t**3 + a*t**2 + b*t - 12
            N = expand(f(2*x - 3))
            D = expand(f(x))
            if all_ok(N, D):
                best.append((a, b, f(5)))
    return best

def skill():
    return max(2*(29 + 5*u) for u in range(-3, 4))

def standard():
    return max(v for _, _, v in cand())

def unique():
    return [standard()]
